import styled from "styled-components";

export const RegisterWrapper = styled.main`
    width: 100%;
    height: 100vh;

    position: relative;

    display: flex;
    align-items: center;
    justify-content: center;

` 
export const BodyRegisterContainer= styled.div`
    width: 100vw;
    height: 50vh;
    display: flex;
    flex-direction: column;
    position:absolute;
   
`

export const CardRegisterContainer = styled.div`
    width:25%;
    height:40%;
   
    position: absolute;
    box-shadow: 5px 4px 6px rgba(0,0,0,0.25);

`
